    uint256 _maxPaymentAmount,
    address _recipient,
    uint256 _discount,
    uint256 _deadline
) external returns (uint256, uint256) {
    if (block.timestamp > _deadline) revert OptionToken_PastDeadline();
    return _exerciseLp(_amount, _maxPaymentAmount, _recipient, _discount);
}
