```

```solidity
    function killGaugeTotally(address _gauge) external {
        if (msg.sender != emergencyCouncil) {
            require(
                IGaugePlugin(gaugePlugin).checkGaugeKillAllowance(
                    msg.sender,
                    _gauge
                ),
                "Restart gauge not allowed"
            );
